const grabacionesDeLlamadas = `-- name: GrabacionesDeLlamadas :many
SELECT llamada_id, estado FROM mensajeria.llamada_grabaciones WHERE llamada_id = ANY ($1::uuid[])
`

type GrabacionesDeLlamadasRow struct {
	LlamadaID uuid.UUID
	Estado    string
}

func (q *Queries) GrabacionesDeLlamadas(ctx context.Context, ids []uuid.UUID) ([]GrabacionesDeLlamadasRow, error) {
	rows, err := q.db.Query(ctx, grabacionesDeLlamadas, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GrabacionesDeLlamadasRow
	for rows.Next() {
		var i GrabacionesDeLlamadasRow
		if err := rows.Scan(&i.LlamadaID, &i.Estado); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

