const receptoresParaLlamada = `-- name: ReceptoresParaLlamada :many
SELECT DISTINCT d.usuario_id FROM mensajeria.disponibilidad d
JOIN nucleo.usuarios u ON u.id = d.usuario_id AND u.activo
JOIN mensajeria.llamada_receptores r ON r.usuario_id = d.usuario_id AND coalesce(r.empresa_id, 0) = $1::bigint
    AND r.recibe AND r.visto_en > $2
WHERE coalesce(d.empresa_id, 0) = $1::bigint AND d.estado = 'disponible'
  AND ($3::bigint IS NULL
       OR EXISTS (SELECT 1 FROM mensajeria.cola_miembros m WHERE m.cola_id = $3::bigint AND m.usuario_id = d.usuario_id)
       OR EXISTS (SELECT 1 FROM mensajeria.cola_supervisores s WHERE s.cola_id = $3::bigint AND s.usuario_id = d.usuario_id))
  -- Quien ya tiene una llamada viva de WhatsApp no recibe otra (las de la centralita no cuentan).
  AND NOT EXISTS (SELECT 1 FROM mensajeria.llamadas l WHERE l.origen = 'whatsapp' AND l.estado IN ('conectando', 'en_curso', 'marcando')
       AND (l.usuario_id = d.usuario_id OR l.reclamada_por = d.usuario_id))
ORDER BY d.usuario_id
`

type ReceptoresParaLlamadaParams struct {
	Empresa   int64
	VivoDesde time.Time
	ColaID    *int64
}

// Quién puede recibir el timbre: disponible, con «Recibir llamadas» encendido y un flujo SSE vivo,
// y que atienda la cola (sin cola, cualquiera de la empresa).
func (q *Queries) ReceptoresParaLlamada(ctx context.Context, arg ReceptoresParaLlamadaParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, receptoresParaLlamada, arg.Empresa, arg.VivoDesde, arg.ColaID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var usuario_id int64
		if err := rows.Scan(&usuario_id); err != nil {
			return nil, err
		}
		items = append(items, usuario_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

