const sumarIntentoRafaga = `-- name: SumarIntentoRafaga :one
UPDATE mensajeria.llamadas SET rafaga_intentos = rafaga_intentos + 1, rafaga_hasta = greatest(rafaga_hasta, $1::timestamptz),
    rafaga_ultimo_call_id = $2::text,
    rafaga_avisada_en = CASE WHEN rafaga_avisada_en IS NULL OR rafaga_avisada_en <= $3::timestamptz
                             THEN $4::timestamptz ELSE rafaga_avisada_en END
WHERE id = $5 AND rafaga_ultimo_call_id IS DISTINCT FROM $2::text
RETURNING rafaga_intentos, (rafaga_avisada_en = $4::timestamptz)::boolean AS avisar
`

type SumarIntentoRafagaParams struct {
	Hasta      time.Time
	CallID     string
	AvisoDesde time.Time
	Ahora      time.Time
	ID         uuid.UUID
}

type SumarIntentoRafagaRow struct {
	RafagaIntentos int32
	Avisar         bool
}

// Un reintento que la ráfaga rechazó, contado en la tarjeta. Un connect repetido (el mismo call_id que
// el último contado) no suma: sin fila. avisar: ya toca refrescar la tarjeta en el feed (la última vez
// fue antes de @aviso_desde, o nunca); se marca en la misma sentencia.
func (q *Queries) SumarIntentoRafaga(ctx context.Context, arg SumarIntentoRafagaParams) (SumarIntentoRafagaRow, error) {
	row := q.db.QueryRow(ctx, sumarIntentoRafaga,
		arg.Hasta,
		arg.CallID,
		arg.AvisoDesde,
		arg.Ahora,
		arg.ID,
	)
	var i SumarIntentoRafagaRow
	err := row.Scan(&i.RafagaIntentos, &i.Avisar)
	return i, err
}

const tocarPestanaDeLlamada = `-- name: TocarPestanaDeLlamada :exec
UPDATE mensajeria.llamadas SET pestana_vista_en = $1
WHERE usuario_id = $2 AND pestana = $3::text AND direccion = 'saliente' AND estado IN ('marcando', 'en_curso')
`

type TocarPestanaDeLlamadaParams struct {
	Ahora     *time.Time
	UsuarioID *int64
	Pestana   string
}

// El latido de una saliente: solo el flujo de eventos de la pestaña desde la que se llamó. Otra
// pestaña del mismo navegador (mismo id de navegador) u otro equipo no la sostienen.
func (q *Queries) TocarPestanaDeLlamada(ctx context.Context, arg TocarPestanaDeLlamadaParams) error {
	_, err := q.db.Exec(ctx, tocarPestanaDeLlamada, arg.Ahora, arg.UsuarioID, arg.Pestana)
	return err
}

const tocarReceptores = `-- name: TocarReceptores :exec
UPDATE mensajeria.llamada_receptores r SET visto_en = $1
WHERE coalesce(r.empresa_id, 0) = $2::bigint AND r.usuario_id = $3
  AND (($4::text IS NULL AND r.recibe) OR r.navegador = $4::text)
`

type TocarReceptoresParams struct {
	Ahora     time.Time
	Empresa   int64
	UsuarioID int64
	Navegador *string
}

// Latido del flujo SSE del usuario.
// El latido de «Recibir llamadas» (entrantes), por navegador: si el flujo dice de qué navegador es,
// toca solo esa fila; sin navegador (paneles viejos), las que reciben llamadas. Una saliente no se
// sostiene con esto: su latido va por pestaña (TocarPestanaDeLlamada).
func (q *Queries) TocarReceptores(ctx context.Context, arg TocarReceptoresParams) error {
	_, err := q.db.Exec(ctx, tocarReceptores,
		arg.Ahora,
		arg.Empresa,
		arg.UsuarioID,
		arg.Navegador,
	)
	return err
}

const tomarAccionesMeta = `-- name: TomarAccionesMeta :many
UPDATE mensajeria.llamadas SET accion_meta_en = $1::timestamptz
WHERE id IN (SELECT l.id FROM mensajeria.llamadas l
    WHERE l.accion_meta_estado = 'pendiente' AND l.accion_meta IN ('reject', 'terminate') AND l.accion_meta_en <= $2
      AND l.estado IN ('terminada', 'perdida', 'rechazada', 'fuera_de_horario', 'fallida')
    ORDER BY l.accion_meta_en LIMIT $3 FOR UPDATE SKIP LOCKED)
RETURNING id, terminada_en
`

type TomarAccionesMetaParams struct {
	Aparte time.Time
	Antes  *time.Time
	Lote   int32
}

type TomarAccionesMetaRow struct {
	ID          uuid.UUID
	TerminadaEn *time.Time
}

// El job de escrituras a Meta toma las reject y terminate pendientes de llamadas ya cerradas cuyo
// intento ya toca (SKIP LOCKED: dos réplicas no toman la misma) y las deja apartadas lote × plazo
// (aparte), para que otro ciclo no las retome mientras este las atiende.
func (q *Queries) TomarAccionesMeta(ctx context.Context, arg TomarAccionesMetaParams) ([]TomarAccionesMetaRow, error) {
	rows, err := q.db.Query(ctx, tomarAccionesMeta, arg.Aparte, arg.Antes, arg.Lote)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TomarAccionesMetaRow
	for rows.Next() {
		var i TomarAccionesMetaRow
		if err := rows.Scan(&i.ID, &i.TerminadaEn); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

